examples.template:
VStack(spacing: 0) {
    MonarchAiSlashCommands(text: $prompt, commands: commands) { command in
        "/\(command.label) "
    }
    TextField({{label}}, text: $prompt, prompt: Text({{placeholder}}), axis: .vertical)
}

examples.setupTemplate:
@State private var prompt = {{typed}}

private let commands = [
    MonarchSlashMenuItem(id: {{commands.0.id}}, label: {{commands.0.name}}, description: {{commands.0.description}}, systemImage: "list.bullet", keywords: ["shorten", "recap"]),
    MonarchSlashMenuItem(id: {{commands.1.id}}, label: {{commands.1.name}}, description: {{commands.1.description}}, systemImage: "pencil"),
    MonarchSlashMenuItem(id: {{commands.2.id}}, label: {{commands.2.name}}, description: {{commands.2.description}}, systemImage: "magnifyingglass"),
    MonarchSlashMenuItem(id: {{commands.3.id}}, label: {{commands.3.name}}, description: {{commands.3.description}}, systemImage: "calendar", isDisabled: {{commands.3.disabled}}),
]

examples.code:
VStack(spacing: 0) {
    MonarchAiSlashCommands(text: $prompt, commands: commands) { command in
        "/\(command.label) "
    }
    TextField("Message the assistant", text: $prompt, prompt: Text("Type / for commands"), axis: .vertical)
}
